'use strict';
// Contract preparation follows ContractViewer's category/rule/auto-analysis branches.
const cwBase={workbench,configPanel,seedConfig,handleAction,modalContent,closeModal,validate,configurationFragment,makeResult,twMountPreview,resultContent,exportRows,doExport,reportText,trDownloadPage};
const CW_TYPES=[['自动','自动识别'],['施工类合同','施工类合同'],['非施工类合同','非施工类合同']];
const cwView={tab:'rules',panel:'materials',query:'',page:1,size:20,resultTask:null,resultTab:'checks',resultQuery:'',resultDoc:'all',resultStatus:'all',resultPage:1,resultSize:20};
let cwSourceReturn=null;
function cwActive(){return state.view==='tool'&&state.toolId==='contract';}
function cwPreparing(){return cwActive()&&!currentTask();}
function cwConfig(){return currentTask()?.config||ws().config;}
function cwEnsure(c){if(!c.contractRuleSets||typeof c.contractRuleSets!=='object'||Array.isArray(c.contractRuleSets))c.contractRuleSets={};if(!c.cwTypeKey)c.cwTypeKey=c.contractType;if(c.contractType!=='自动'&&!c.contractRuleSets[c.contractType])c.contractRuleSets[c.contractType]={rules:structuredClone(c.contractRules||[]),checks:[...(c.checks||[])]};return c;}
seedConfig=function(id,c){cwBase.seedConfig(id,c);if(id==='contract'&&c===state.work.contract?.config&&!state.work.contract.taskId)cwEnsure(c);return c;};
function cwSaveCategory(c){if(c.cwTypeKey&&c.cwTypeKey!=='自动')c.contractRuleSets[c.cwTypeKey]={rules:structuredClone(c.contractRules),checks:[...c.checks]};}
function cwSwitchCategory(value){const c=cwEnsure(ws().config);cwSaveCategory(c);c.contractType=value;c.cwTypeKey=value;if(value!=='自动'){const saved=c.contractRuleSets[value]||{rules:[],checks:[]};c.contractRules=structuredClone(saved.rules);c.checks=[...saved.checks];}cwView.query='';cwView.page=1;render();}
function cwSelected(c){return(c.contractRules||[]).filter(r=>(c.checks||[]).includes(r.title));}
function cwText(v){if(v===undefined||v===null)return '未提供';if(typeof v==='string')return v||'未提供';return JSON.stringify(v,null,2);}
function cwValue(v){if(v&&typeof v==='object'&&!Array.isArray(v))return '<dl class="cw-values">'+Object.entries(v).map(([k,v])=>'<dt>'+E(k)+'</dt><dd>'+E(cwText(v))+'</dd>').join('')+'</dl>';return '<div class="cw-value-text">'+E(cwText(v))+'</div>';}
function cwRuleSearch(c=cwConfig()){const q=cwView.query.trim().toLowerCase();return(c.contractRules||[]).map((r,index)=>({r,index})).filter(({r})=>[r.title,r.description,r.laws,r.judgment].join(' ').toLowerCase().includes(q));}
function cwRuleTable(c=cwConfig()){const rows=cwRuleSearch(c),locked=!!currentTask(),pages=Math.max(1,Math.ceil(rows.length/cwView.size));cwView.page=Math.max(1,Math.min(cwView.page,pages));const page=rows.slice((cwView.page-1)*cwView.size,cwView.page*cwView.size),selected=new Set(c.checks||[]),all=page.length&&page.every(({r})=>selected.has(r.title)),some=page.some(({r})=>selected.has(r.title));return '<div class="cw-table-scroll"><table class="cw-table cw-rule-table"><thead><tr><th><label><input type="checkbox" data-cw-change="rule-page" aria-label="选择本页检查规则" aria-checked="'+(some&&!all?'mixed':!!all)+'" '+(all?'checked':'')+' '+(locked||!page.length?'disabled':'')+'>本页</label></th><th>检查事项</th><th>检查说明</th><th>操作</th></tr></thead><tbody>'+page.map(({r,index})=>'<tr><td><input type="checkbox" data-cw-change="rule" data-index="'+index+'" aria-label="选择'+E(r.title)+'" '+(selected.has(r.title)?'checked':'')+' '+(locked?'disabled':'')+'></td><td>'+A(E(r.title),'cw-rule','data-index="'+index+'"')+'</td><td><div class="cw-two-lines">'+E(r.description)+'</div></td><td>'+A(locked?'查看':'编辑','cw-rule','data-index="'+index+'"')+'</td></tr>').join('')+'</tbody></table>'+(!rows.length?'<div class="cw-empty">'+(cwView.query?'没有匹配的检查规则。':'此类别尚未配置规则。请新增规则，或开启“补充查找线索”。')+'</div>':'')+'</div><div class="cw-pager"><span>共 <strong>'+rows.length+'</strong> 项'+(cwView.query?'匹配规则':'规则')+'</span><label>每页 <select data-cw-change="rule-size" aria-label="每页规则数">'+[20,50,100].map(n=>'<option value="'+n+'" '+(n===cwView.size?'selected':'')+'>'+n+'</option>').join('')+'</select> 项</label><div>'+B('上一页','cw-rule-page','sm','data-step="-1" '+(cwView.page===1?'disabled':''))+'<span>第 '+cwView.page+' / '+pages+' 页</span>'+B('下一页','cw-rule-page','sm','data-step="1" '+(cwView.page===pages?'disabled':''))+'</div></div>';}
function cwPaintRules(){const holder=$('#cw-rule-list');if(holder)holder.innerHTML=cwRuleTable();const count=$('#cw-selected-count');if(count)count.textContent=cwSelected(cwConfig()).length;const check=$('[data-cw-change="rule-page"]');if(check)check.indeterminate=check.getAttribute('aria-checked')==='mixed';}
function cwOptions(c,locked){return '<div class="cw-options-body">'+pgStageCard('contract','compliance',c,locked)+pgStageCard('contract','information',c,locked)+'<section class="cw-attachment-option"><label><input type="checkbox" data-config="merge" '+(c.merge?'checked':'')+' '+(locked?'disabled':'')+'>关联附件一并分析</label><p>补充协议、技术要求等资料，请从左侧对应合同的附件图标关联。</p>'+(!locked?B('管理当前合同附件','attachments','sm','data-id="'+E(ws().preview||ws().ids[0]||'')+'" '+(!ws().ids.length?'disabled':'')):B('查看本次附件','tr-attachments','sm','data-id="'+E(currentTask().id)+'"'))+'</section>'+'</div>';}
function cwPanel(){const c=cwConfig(),locked=!!currentTask(),auto=c.contractType==='自动';return '<aside class="config ew-config tw-config pg-config cw-config"><div class="cw-panel-head"><h2><span class="tw-step">'+(locked?'执行配置':'Step 2')+'</span> 设置合同检查</h2></div><div class="cw-category"><label>合同类别<select data-cw-change="category" aria-label="合同类别" '+(locked?'disabled':'')+'>'+CW_TYPES.map(([v,n])=>'<option value="'+v+'" '+(c.contractType===v?'selected':'')+'>'+n+'</option>').join('')+'</select></label><label class="cw-auto-check"><input type="checkbox" data-cw-change="auto" '+(c.autoAnalysis?'checked':'')+' '+(locked?'disabled':'')+'>补充查找线索<span title="原功能：自动分析。手动点击开始分析后，在规则检查之外由模型补充分析。">'+I('help','icon-sm')+'</span></label></div><p class="cw-category-help">'+(auto?'逐份识别合同类别并分析，直接点击“开始分析”即可。':'选择要检查的事项；同一批合同使用下方已选规则。')+'</p>'+(auto?'<div class="cw-auto-body"><h3>自动识别合同类别</h3><p>系统根据每份合同内容选择分析方式，整理条款及待核验线索。</p><p>需要指定检查事项时，可选择“施工类合同”或“非施工类合同”。</p>'+cwOptions(c,locked).replace(/<section class="pg-stage-card"[\s\S]*?<\/section>/g,'')+'</div>':'<nav class="cw-setting-tabs" role="tablist" aria-label="合同检查设置">'+[['rules','检查规则'],['options','提示词与附件']].map(([key,n])=>'<button role="tab" aria-selected="'+(cwView.tab===key)+'" data-action="cw-tab" data-tab="'+key+'" class="'+(cwView.tab===key?'active':'')+'">'+n+(key==='rules'?' <strong>'+c.contractRules.length+'</strong>':'')+'</button>').join('')+'</nav>'+(cwView.tab==='options'?cwOptions(c,locked):'<div class="cw-rule-toolbar"><div>已选 <strong id="cw-selected-count">'+cwSelected(c).length+'</strong> 项'+(!locked?' '+A('选择全部规则','cw-rule-all')+' '+A('取消全部','cw-rule-none'):'')+'</div><div class="search">'+I('search','icon-sm')+'<input id="cw-rule-query" data-cw-input="rules" aria-label="查找合同检查规则" placeholder="查找检查事项或说明" value="'+E(cwView.query)+'"></div>'+(!locked?B('新增规则','cw-rule-new','soft sm'):'')+'</div><div id="cw-rule-list" class="cw-rule-list">'+cwRuleTable(c)+'</div>'))+'</aside>';}
function cwMaterials(){const root=document.createElement('div');root.innerHTML=twMaterials();const head=root.querySelector('.tw-panel-head h2');if(head){head.innerHTML='<span class="tw-step">Step 1</span> 合同资料';head.parentElement.insertAdjacentHTML('beforeend',B('添加资料','add-tool-materials','soft sm','aria-label="添加合同资料"'));}const intro=root.querySelector('.tw-intro');if(intro)intro.textContent='添加本次检查的合同；补充协议、技术附件可逐份关联。';return root.innerHTML;}
configPanel=function(){return cwActive()?cwPanel():cwBase.configPanel();};
workbench=function(){if(!cwPreparing())return cwBase.workbench();const w=ws();if(!w.ids.includes(w.preview))w.preview=w.ids[0]||null;return '<div class="ew-workspace tw-workspace cw-workspace">'+twHeader()+'<nav class="cw-mobile-tabs" aria-label="合同分析工作区">'+B('合同资料','cw-panel',cwView.panel==='materials'?'active':'','data-panel="materials"')+B('检查内容','cw-panel',cwView.panel==='config'?'active':'','data-panel="config"')+'</nav><div class="cw-layout" data-cw-panel="'+cwView.panel+'">'+cwMaterials()+cwPanel()+'</div></div>';};
twMountPreview=function(){if(cwPreparing())return;return cwBase.twMountPreview();};
function cwRuleDraft(index=-1){const c=cwConfig(),r=index>=0?c.contractRules[index]:{title:'',description:'',laws:'',judgment:'',format:'compliance',expected:'',enabled:true},draft=structuredClone(r);let object=draft.completenessBuffer||{};if(draft.format==='completeness'){try{object=JSON.parse(draft.expected||'{}');}catch{object={};}}return{index,draft,text:draft.format==='compliance'?draft.expected||'':draft.textBuffer||'',pairs:Object.entries(object).map(([key,value])=>({key,value:typeof value==='string'?value:JSON.stringify(value),rawValue:value,modified:false})),original:JSON.stringify(draft)};}
function cwRuleField(key,label,placeholder,d,locked){const attrs=' data-cw-edit="'+key+'" '+(locked?'readonly':'')+' placeholder="'+placeholder+'"';return '<label class="field"><span>'+label+' <b class="red">*</b></span>'+(key==='title'?'<input maxlength="150"'+attrs+' value="'+E(d[key])+'">':'<textarea rows="3"'+attrs+'>'+E(d[key])+'</textarea>')+'</label>';}
function cwRuleModal(p){const locked=!!currentTask(),d=p.draft,fields=[['title','检查事项（规则名称）','例如：付款条件与付款凭证'],['description','检查说明','说明需要从合同中提取和核对的内容。'],['laws','判断依据','填写适用法规、制度或合同约定。'],['judgment','判定标准','说明什么情况符合、什么情况需要进一步核验。']];const pairs='<div class="cw-pairs">'+p.pairs.map((pair,i)=>'<div><input data-cw-pair="key" data-index="'+i+'" aria-label="字段名称 '+(i+1)+'" placeholder="字段名称" value="'+E(pair.key)+'" '+(locked?'readonly':'')+'><input data-cw-pair="value" data-index="'+i+'" aria-label="字段说明 '+(i+1)+'" placeholder="提取说明或内容" value="'+E(pair.value)+'" '+(locked?'readonly':'')+'>'+(!locked?B('移除','cw-pair-remove','ghost sm','data-index="'+i+'"'):'')+'</div>').join('')+(!locked?B('添加字段','cw-pair-add','sm'):'')+'</div>';return modalFrame(locked?'查看检查规则':p.index<0?'新增检查规则':'编辑检查规则','明确检查什么、依据什么、如何判断。','<div class="cw-rule-fields">'+fields.map(([key,label,placeholder])=>cwRuleField(key,label,placeholder,d,locked)).join('')+'</div><details class="cw-extraction-format" '+(d.format==='completeness'?'open':'')+'><summary>提取内容与格式</summary><label class="field"><span>结果格式</span><select data-cw-change="format" '+(locked?'disabled':'')+'><option value="compliance" '+(d.format==='compliance'?'selected':'')+'>文本内容</option><option value="completeness" '+(d.format==='completeness'?'selected':'')+'>分字段内容</option></select></label>'+(d.format==='compliance'?'<label class="field"><span>提取内容</span><textarea rows="3" data-cw-edit="expected" '+(locked?'readonly':'')+'>'+E(p.text)+'</textarea></label>':pairs)+'</details><p id="cw-rule-error" class="error" role="alert"></p>',B(locked?'关闭':'取消','close-modal')+(locked?'':(p.index>=0?B('删除规则','cw-rule-delete','danger ghost'):'')+B('保存规则','cw-rule-save','primary')),'cw-rule-dialog');}
function cwSerializeDraft(p){const d=structuredClone(p.draft),keys=p.pairs.map(r=>r.key.trim()),object=Object.fromEntries(p.pairs.map(r=>[r.key.trim(),!r.modified&&Object.hasOwn(r,'rawValue')?r.rawValue:r.value]));if(d.format==='completeness'){if(keys.some(k=>!k)||new Set(keys).size!==keys.length)throw Error('字段名称不能为空或重复。');if(keys.some(k=>['__proto__','constructor','prototype'].includes(k)))throw Error('请使用有效的业务字段名。');d.expected=JSON.stringify(object,null,2);}else d.expected=p.text;d.textBuffer=p.text;d.completenessBuffer=object;return d;}
validate=function(show=true){if(!cwPreparing())return cwBase.validate(show);const c=ws().config,auto=c.contractType==='自动',skip=new Set(['请至少选择一个关注点或检查规则','合同规则的名称、描述、依据和判断标准均需填写',...PROMPT_STAGES.contract.map(([,label])=>'请填写'+label+'的提示词')]),errors=cwBase.validate(false).filter(e=>!skip.has(e));if(!auto){const rules=cwSelected(c);if(!rules.length&&!c.autoAnalysis)errors.push('请选择检查规则，或开启“补充查找线索”。');for(const r of rules){if([r.title,r.description,r.laws,r.judgment].some(v=>!String(v||'').trim()))errors.push('请补全检查规则的名称、说明、依据和判定标准。');if(r.format==='completeness'){try{const v=JSON.parse(r.expected||'{}');if(!v||typeof v!=='object'||Array.isArray(v))throw Error();}catch{errors.push('请检查分字段提取内容的格式。');}}}}const out=[...new Set(errors)];if(show&&out.length)openModal('validation',{errors:out});return out;};
configurationFragment=function(id,c){if(id!=='contract')return cwBase.configurationFragment(id,c);const category={'自动':'auto','施工类合同':'construction','非施工类合同':'non_construction'}[c.contractType]||'auto',button=c.autoAnalysis?1:0,settings=category==='auto'?{button}:{information_extraction:cwSelected(c).map(r=>({title:r.title,description:r.description,laws_and_regulations:r.laws,judgment_rule:r.judgment,extracted_value:r.format==='completeness'?JSON.parse(r.expected||'{}'):r.expected??''})),compliance_analysis_prompt:c.stages.compliance?.content??null,information_extraction_prompt:c.stages.information?.content??null,button};return{exec_mode:'custom',custom_config:{contract_category:category,parameter_template:'{"rules": []}',prompt_uuid:'prompt',button,parameter_settings:settings}};};
makeResult=function(t){const source=t.toolId==='contract'&&t.config.contractType==='自动'?{...t,config:{...t.config,checks:[],contractRules:[]}}:t,rows=cwBase.makeResult(source);if(t.toolId!=='contract')return rows;if(rows.length)return rows;return(t.successIds||[]).map(id=>({doc:id,title:file(id)?.title||file(id)?.name||'合同资料',unit:file(id)?.unit,date:file(id)?.date,amount:file(id)?.amount,check:'合同自动分析',judgment:'未提供',autoAnalysis:true,excerpt:previewText(file(id)).split('\n').filter(Boolean)[0]||'',detail:'本次未返回规则级判断，请结合合同原文和相关业务凭证继续核验。'}));};
function cwNormalize(t){const allowed=new Set([...(t.ids||[]),...(t.config.merge?Object.values(t.attachments||{}).flat():[])]);return(t.result||[]).map((r,index)=>{const doc=r.doc||r.file_uuid||(t.ids?.length===1?t.ids[0]:null),refs=[...new Set([doc,...(Array.isArray(r.refs)?r.refs:[])].filter(Boolean))],rule=t.config.contractRules?.find(q=>q.title===(r.check||r.title));return{index,raw:r,doc,refs,scopeValid:refs.every(id=>allowed.has(id)),title:r.check||r.subject||r.title||'合同检查',value:Object.hasOwn(r,'extracted_value')?r.extracted_value:r.extractedValue??r.excerpt??r.autoAnalysisText,judgment:String(r.result??r.judgment??'未提供'),basis:r.laws_and_regulations||r.criteria||rule?.laws||'',standard:r.judgment_rule||r.judgmentRule||rule?.judgment||'',analysis:cwText(r.analysis??r.detail??r.autoAnalysisText??''),advice:r.advice||r.suggestion||'',automatic:!!r.autoAnalysis||typeof r.autoAnalysisText==='string'};});}
function cwReadable(row,download=false){return row.scopeValid!==false&&row.refs.length>0&&row.refs.every(id=>{const d=file(id),p=d&&!d.deleted&&auditFileAccess(d);return p&&p.read&&(!download||p.download);});}
function cwResultState(row){const s=row.judgment.trim().toLowerCase();return ['false','不符合'].includes(s)||/需关注|待核验|异常|不合规/.test(s)?'needs':/不足|缺失|未提取|无法判断/.test(s)?'insufficient':['true','符合'].includes(s)?'clear':'unknown';}
function cwResultColor(row){return cwResultState(row)==='clear'?'green':cwResultState(row)==='needs'?'red':cwResultState(row)==='insufficient'?'amber':'';}
function cwJudgmentLabel(row){const value=row.judgment.trim().toLowerCase();return value==='true'?'符合':value==='false'?'不符合':row.judgment;}
function cwRV(t){if(cwView.resultTask!==t.id){Object.assign(cwView,{resultTask:t.id,resultTab:'checks',resultQuery:'',resultDoc:'all',resultStatus:'all',resultPage:1});}return cwView;}
function cwFiltered(t){const v=cwRV(t),q=v.resultQuery.trim().toLowerCase();return cwNormalize(t).filter(r=>cwReadable(r)&&(v.resultDoc==='all'||r.doc===v.resultDoc)&&(v.resultStatus==='all'||cwResultState(r)===v.resultStatus)&&(!q||[r.title,cwText(r.value),r.analysis,r.basis,file(r.doc)?.name].join(' ').toLowerCase().includes(q)));}
function cwResultTable(t){const v=cwRV(t),rows=cwFiltered(t),pages=Math.max(1,Math.ceil(rows.length/v.resultSize));v.resultPage=Math.max(1,Math.min(v.resultPage,pages));return '<div class="cw-result-table-scroll"><table class="cw-table cw-result-table"><thead><tr><th>检查事项 / 合同</th><th>判断结果</th><th>提取内容</th><th>核验</th></tr></thead><tbody>'+rows.slice((v.resultPage-1)*v.resultSize,v.resultPage*v.resultSize).map(r=>'<tr><td><strong>'+E(r.title)+'</strong><small>'+E(file(r.doc)?.name||'原文件已移除')+(r.automatic?' · 自动分析':'')+'</small></td><td>'+tag(cwJudgmentLabel(r),cwResultColor(r))+'</td><td><div class="cw-two-lines">'+E(cwText(r.value).slice(0,220))+'</div></td><td>'+A('查看依据','cw-result-detail','data-index="'+r.index+'"')+'</td></tr>').join('')+'</tbody></table>'+(!rows.length?'<div class="cw-empty">没有匹配的结果，可调整筛选条件。</div>':'')+'</div><div class="cw-pager"><span>共 <strong>'+rows.length+'</strong> 条</span><div>'+B('上一页','cw-result-page','sm','data-step="-1" '+(v.resultPage===1?'disabled':''))+'<span>第 '+v.resultPage+' / '+pages+' 页</span>'+B('下一页','cw-result-page','sm','data-step="1" '+(v.resultPage===pages?'disabled':''))+'</div></div>';}
function cwInfo(t){const rows=[...new Map(cwNormalize(t).filter(r=>cwReadable(r)).map(r=>[r.doc,r.raw])).entries()];return '<div class="cw-info-table">'+simpleTable(['合同资料','涉及单位','金额与单位','关键日期','核验'],rows.map(([id,r])=>[E(file(id)?.name||'原资料已移除'),E(r.unit??'未提供'),E(r.amount??'未提供'),E(r.date??'未提供'),A('查看原文','source','data-id="'+E(id)+'"')]),true)+'</div>';}
resultContent=function(t){if(t.toolId!=='contract')return cwBase.resultContent(t);const v=cwRV(t),all=cwNormalize(t).filter(r=>cwReadable(r)),needs=all.filter(r=>cwResultState(r)==='needs').length,insufficient=all.filter(r=>cwResultState(r)==='insufficient').length;return '<section class="cw-results"><div class="cw-result-top"><nav role="tablist" aria-label="合同分析结果">'+[['checks','检查结果'],['info','合同基础信息']].map(([key,n])=>'<button role="tab" aria-selected="'+(v.resultTab===key)+'" class="'+(v.resultTab===key?'active':'')+'" data-action="cw-result-tab" data-tab="'+key+'">'+n+'</button>').join('')+'</nav>'+B(t.reportGenerating?'报告生成中…':t.report?'查看分析报告':'生成分析报告','contract-report','sm',t.reportGenerating?'disabled':'')+'</div><div class="cw-result-summary"><span>检查结果 <strong>'+all.length+'</strong> 条</span><span>待核验 <strong>'+needs+'</strong> 条</span><span>资料不足 <strong>'+insufficient+'</strong> 条</span><small>“已提取”仅表示返回了内容，请继续核对判断依据。</small></div>'+(v.resultTab==='info'?cwInfo(t):'<div class="cw-result-filters"><select aria-label="合同结果文件范围" data-cw-change="result-doc"><option value="all">全部合同</option>'+[...new Set(all.map(r=>r.doc))].map(id=>'<option value="'+E(id)+'" '+(v.resultDoc===id?'selected':'')+'>'+E(file(id)?.name)+'</option>').join('')+'</select><select aria-label="判断结果范围" data-cw-change="result-status">'+[['all','全部判断结果'],['needs','待核验'],['insufficient','资料不足'],['clear','符合'],['unknown','其他 / 未说明']].map(([key,n])=>'<option value="'+key+'" '+(v.resultStatus===key?'selected':'')+'>'+n+'</option>').join('')+'</select><div class="search">'+I('search','icon-sm')+'<input id="cw-result-query" data-cw-input="result" aria-label="查找合同结果" placeholder="查找事项、合同或提取内容" value="'+E(v.resultQuery)+'"></div>'+A('重置','cw-result-reset')+'</div><div id="cw-result-list" class="cw-result-list">'+cwResultTable(t)+'</div>')+'</section>';};
function cwReportRows(t){return cwNormalize(t).filter(r=>cwReadable(r));}
function cwReportMarkup(t){return '<article class="cw-report"><h2>合同分析报告</h2><p>'+E(t.name)+'</p>'+cwReportRows(t).map((r,i)=>'<section><h3>'+(i+1)+'　'+E(r.title)+' · '+E(cwJudgmentLabel(r))+'</h3><h4>提取内容</h4>'+cwValue(r.value)+'<h4>判断依据</h4><p>'+E(r.basis||'未提供')+'</p><h4>判定标准</h4><p>'+E(r.standard||'未提供')+'</p><h4>分析说明</h4><p>'+E(r.analysis||'未提供')+'</p>'+(r.advice?'<h4>后续核验</h4><p>'+E(r.advice)+'</p>':'')+'<p>来源：'+r.refs.map(id=>E(file(id)?.name||'原文件已移除')).join('、')+'</p></section>').join('')+'</article>';}
function cwReportText(t){return '合同分析报告\n任务：'+t.name+'\n\n'+cwReportRows(t).map((r,i)=>(i+1)+' '+r.title+' · '+cwJudgmentLabel(r)+'\n提取内容：'+cwText(r.value)+'\n判断依据：'+(r.basis||'未提供')+'\n判定标准：'+(r.standard||'未提供')+'\n分析说明：'+(r.analysis||'未提供')+'\n来源：'+r.refs.map(id=>file(id)?.name||'原文件已移除').join('；')).join('\n\n');}
modalContent=function(){if(!cwActive())return cwBase.modalContent();if(modal==='cw-rule')return cwRuleModal(modalData);if(modal==='cw-rule-delete-confirm')return modalFrame('删除检查规则','仅移除本次配置中的规则。','<p>'+E(modalData.back.draft.title)+'</p>',B('取消','close-modal')+B('确认删除','cw-rule-delete-confirm','danger'),'small');if(modal==='cw-result-detail'){const t=currentTask(),r=cwNormalize(t).find(r=>r.index===modalData.index);if(!r||!cwReadable(r))return modalFrame('无法查看依据','','来源已移除或没有查看权限。',B('关闭','close-modal'),'medium');return modalFrame(r.title,file(r.doc)?.name||'合同资料','<div class="cw-result-judgment">'+tag(cwJudgmentLabel(r),cwResultColor(r))+(r.automatic?tag('自动分析','blue'):'')+'</div><section class="cw-evidence-section"><h3>提取内容 / 原文条款</h3>'+cwValue(r.value)+'</section><section class="cw-evidence-section"><h3>判断依据</h3><p>'+E(r.basis||'本条未提供判断依据。')+'</p><h3>判定标准</h3><p>'+E(r.standard||'本条未提供判定标准。')+'</p></section><section class="cw-evidence-section"><h3>分析说明</h3><p>'+E(r.analysis||'本条未提供分析说明。')+'</p>'+(r.advice?'<h3>后续核验</h3><p>'+E(r.advice)+'</p>':'')+'</section><section class="cw-evidence-section"><h3>核验来源</h3>'+r.refs.map(id=>auditFileAccess(file(id)).preview?B(E(file(id)?.name),'source','sm','data-id="'+E(id)+'"'):'<p>'+E(file(id)?.name)+'（无预览权限）</p>').join('')+'</section>',B('关闭','close-modal'),'cw-evidence-dialog');}if(modal==='contract-report')return modalFrame('合同分析报告','根据本次返回结果整理，保留判断依据和原文来源。',cwReportMarkup(currentTask()),B('关闭','close-modal')+B('下载文本','download-contract')+B('下载 Word','cw-report-word','primary',trCanDownload(currentTask())?'':'disabled'),'cw-report-dialog');return cwBase.modalContent();};
closeModal=function(){if(cwActive()&&modal==='source'&&cwSourceReturn){const back=cwSourceReturn;cwSourceReturn=null;cwBase.closeModal();openModal('cw-result-detail',back);return;}if(modal==='cw-rule-delete-confirm'){openModal('cw-rule',modalData.back);return;}return cwBase.closeModal();};
exportRows=function(t,scope='all'){if(t.toolId!=='contract')return cwBase.exportRows(t,scope);const rows=cwNormalize(t).filter(r=>cwReadable(r,true)&&(scope==='all'||r.doc===scope));return [['来源合同','检查事项','提取内容','判断依据','判定标准','分析说明','判断结果','结果来源'],...rows.map(r=>[file(r.doc)?.name,r.title,cwText(r.value),r.basis,r.standard,r.analysis,r.judgment,r.automatic?'自动分析':'规则检查'])];};
doExport=function(){const t=currentTask();if(t?.toolId!=='contract'||$('#export-format')?.value!=='json')return cwBase.doExport();if(!trCanDownload(t))return toast('当前结果暂无下载权限。');const scope=$('#export-scope')?.value||'all',rows=cwNormalize(t).filter(r=>cwReadable(r,true)&&(scope==='all'||r.doc===scope));if(!rows.length)return toast('当前范围没有可导出的结果。');download((t.name||'合同分析')+'-结果.json',JSON.stringify({task:t.name,scope:scope==='all'?'本次全部结果':file(scope)?.name,config:t.config,execution_config:t.configFragment,attachments:t.attachments,results:rows.map(r=>r.raw)},null,2),'application/json;charset=utf-8');closeModal();};
reportText=function(t,title){return t.toolId==='contract'?cwReportText(t):cwBase.reportText(t,title);};
trDownloadPage=function(t){const html=cwBase.trDownloadPage(t);if(t.toolId!=='contract')return html;const root=document.createElement('div');root.innerHTML=html;const card=root.querySelector('[data-kind="contract"]')?.closest('article');if(card){card.querySelector('small').textContent='Word / TXT';card.querySelector('p').textContent='提取内容、判断依据、分析说明和原文来源。';}return root.innerHTML;};
handleAction=function(action,el){if(!cwActive())return cwBase.handleAction(action,el);const d=el?.dataset||{},v=cwView;
 if(action==='cw-panel'){v.panel=d.panel;render();return;}if(action==='cw-tab'){v.tab=d.tab;render();return;}
 if(action==='cw-rule'||action==='cw-rule-new'){openModal('cw-rule',cwRuleDraft(action==='cw-rule-new'?-1:Number(d.index)));return;}
 if(action==='cw-rule-page'){v.page+=Number(d.step);cwPaintRules();return;}
 if(action==='cw-pair-add'&&modal==='cw-rule'&&!currentTask()){modalData.pairs.push({key:'',value:''});paintModal();return;}
 if(action==='cw-pair-remove'&&modal==='cw-rule'&&!currentTask()){modalData.pairs.splice(Number(d.index),1);paintModal();return;}
 if(action==='cw-rule-save'&&!currentTask()&&modal==='cw-rule'){try{const p=modalData,r=cwSerializeDraft(p),c=ws().config;for(const key of ['title','description','laws','judgment'])r[key]=r[key].trim();if(['title','description','laws','judgment'].some(k=>!r[k]))throw Error('请填写检查事项、说明、依据和判定标准。');if(c.contractRules.some((x,i)=>i!==p.index&&x.title===r.title))throw Error('已有同名规则，请调整检查事项名称。');const old=c.contractRules[p.index],enabled=old?c.checks.includes(old.title):true;if(p.index<0)c.contractRules.push(r);else c.contractRules[p.index]=r;c.checks=c.checks.filter(k=>k!==old?.title);if(enabled)c.checks.push(r.title);r.enabled=enabled;cwSaveCategory(c);cwBase.closeModal();render();}catch(e){$('#cw-rule-error').textContent=e.message;}return;}
 if(action==='cw-rule-delete'&&!currentTask()&&modal==='cw-rule'){openModal('cw-rule-delete-confirm',{back:structuredClone(modalData)});return;}
 if(action==='cw-rule-delete-confirm'&&!currentTask()&&modal==='cw-rule-delete-confirm'){const c=ws().config,i=modalData.back.index,r=c.contractRules[i];c.contractRules.splice(i,1);c.checks=c.checks.filter(k=>k!==r.title);cwSaveCategory(c);cwBase.closeModal();render();return;}
 if(action==='cw-rule-all'||action==='cw-rule-none'){if(currentTask())return;const c=ws().config;c.checks=action==='cw-rule-all'?c.contractRules.map(r=>r.title):[];c.contractRules.forEach(r=>r.enabled=c.checks.includes(r.title));cwSaveCategory(c);cwPaintRules();persist();return;}
 if(action==='cw-result-tab'){v.resultTab=d.tab;render();return;}
 if(action==='cw-result-page'){v.resultPage+=Number(d.step);$('#cw-result-list').innerHTML=cwResultTable(currentTask());return;}
 if(action==='cw-result-reset'){Object.assign(v,{resultQuery:'',resultDoc:'all',resultStatus:'all',resultPage:1});render();return;}
 if(action==='cw-result-detail'){openModal('cw-result-detail',{index:Number(d.index)});return;}
 if(action==='result-detail'&&currentTask()){openModal('cw-result-detail',{index:Number(d.index)});return;}
 if(action==='source'&&modal==='cw-result-detail')cwSourceReturn=structuredClone(modalData);
 if(action==='cw-report-word'){const t=currentTask();if(!trCanDownload(t))return toast('当前结果暂无下载权限。');download((t.name||'合同分析')+'-分析报告.docx',v6Docx(cwReportText(t).split('\n')),'application/vnd.openxmlformats-officedocument.wordprocessingml.document');return;}
 if(action==='tr-artifact'&&d.kind==='contract'&&currentTask()){if(!trCanDownload(currentTask()))return toast('当前结果暂无下载权限。');return cwBase.handleAction('contract-report',el);}
 if(action==='download-contract'&&currentTask()&&!trCanDownload(currentTask()))return toast('当前结果暂无下载权限。');
 if(cwPreparing()&&['tw-preview','preview'].includes(action)){ws().preview=d.id;return cwBase.handleAction('source',el);}
 if(cwPreparing()&&action==='tw-panel'){v.panel=d.panel==='materials'?'materials':'config';render();return;}
 return cwBase.handleAction(action,el);
};
window.addEventListener('change',e=>{if(!cwActive())return;const el=e.target,key=el.dataset.cwChange;if(!key)return;e.stopImmediatePropagation();if(key==='result-doc'||key==='result-status'){cwView[key==='result-doc'?'resultDoc':'resultStatus']=el.value;cwView.resultPage=1;$('#cw-result-list').innerHTML=cwResultTable(currentTask());return;}if(key==='rule-size'){cwView.size=Number(el.value);cwView.page=1;cwPaintRules();return;}if(currentTask())return;const c=ws().config;if(key==='category')return cwSwitchCategory(el.value);if(key==='auto'){c.autoAnalysis=el.checked;persist();return;}if(key==='rule'){const r=c.contractRules[Number(el.dataset.index)];c.checks=el.checked?[...new Set([...c.checks,r.title])]:c.checks.filter(k=>k!==r.title);r.enabled=el.checked;cwSaveCategory(c);cwPaintRules();persist();return;}if(key==='rule-page'){const page=cwRuleSearch(c).slice((cwView.page-1)*cwView.size,cwView.page*cwView.size),names=new Set(page.map(x=>x.r.title));c.checks=el.checked?[...new Set([...c.checks,...names])]:c.checks.filter(k=>!names.has(k));c.contractRules.forEach(r=>r.enabled=c.checks.includes(r.title));cwSaveCategory(c);cwPaintRules();persist();return;}if(key==='format'&&modal==='cw-rule'){modalData.draft.format=el.value;paintModal();}},true);
window.addEventListener('input',e=>{if(!cwActive())return;const el=e.target,key=el.dataset.cwInput;if(key){e.stopImmediatePropagation();if(key==='rules'){cwView.query=el.value;cwView.page=1;cwPaintRules();}if(key==='result'){cwView.resultQuery=el.value;cwView.resultPage=1;$('#cw-result-list').innerHTML=cwResultTable(currentTask());}return;}if(modal==='cw-rule'&&!currentTask()){if(el.dataset.cwEdit){e.stopImmediatePropagation();if(el.dataset.cwEdit==='expected')modalData.text=el.value;else modalData.draft[el.dataset.cwEdit]=el.value;}if(el.dataset.cwPair){e.stopImmediatePropagation();const pair=modalData.pairs[Number(el.dataset.index)];pair[el.dataset.cwPair]=el.value;if(el.dataset.cwPair==='value')pair.modified=true;}}},true);
render();
